import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

sheet_name = vals.active.title
vws = vals[sheet_name]
ws = wb[sheet_name]

def norm(x):
    if x is None:
        return ""
    if isinstance(x, float) and x.is_integer():
        return str(int(x))
    return str(x).strip()

lookup = []
for r in range(2, vws.max_row + 1):
    s = norm(vws.cell(r, 19).value)  # S: NUMVAL
    o = norm(vws.cell(r, 15).value)  # O: LASTNAME
    p = norm(vws.cell(r, 16).value)  # P: FIRSTNAME
    v = vws.cell(r, 22).value        # V: DESCRIPTION
    if s or o or p:
        lookup.append((s, o, p, v))

results = []
for r in range(2, 17):
    a = norm(vws.cell(r, 1).value)   # A: ClientID
    f = norm(vws.cell(r, 6).value)   # F: LastName
    g = norm(vws.cell(r, 7).value)   # G: FirstName

    found = None
    if a:
        for s, o, p, v in lookup:
            if s == a and o == f and p == g:
                found = v
                break

    if found is not None:
        if isinstance(found, str):
            found = found.strip()
            if found == "":
                found = None

    ws.cell(r, 2).value = found
    results.append(found)

wb.save(OUT)

print("sheet:", sheet_name)
print("lookup_rows:", len(lookup))
print("B2:B16:", results)
